package ext

import "fmt"

type Document struct {
	Version   string     `yaml:"version,omitempty"`
	Namespace string     `yaml:"namespace,omitempty"`
	Flags     []*Flag    `yaml:"flags,omitempty"`
	Segments  []*Segment `yaml:"segments,omitempty"`
}

type Flag struct {
	Key         string     `yaml:"key,omitempty"`
	Name        string     `yaml:"name,omitempty"`
	Type        string     `yaml:"type,omitempty"`
	Description string     `yaml:"description,omitempty"`
	Enabled     bool       `yaml:"enabled"`
	Variants    []*Variant `yaml:"variants,omitempty"`
	Rules       []*Rule    `yaml:"rules,omitempty"`
	Rollouts    []*Rollout `yaml:"rollouts,omitempty"`
}

type Variant struct {
	Key         string      `yaml:"key,omitempty"`
	Name        string      `yaml:"name,omitempty"`
	Description string      `yaml:"description,omitempty"`
	Attachment  interface{} `yaml:"attachment,omitempty"`
}

type Rule struct {
	Segment       *SegmentEmbed   `yaml:"segment,omitempty"`
	Rank          uint            `yaml:"rank,omitempty"`
	Distributions []*Distribution `yaml:"distributions,omitempty"`
}

// IsSegment is implemented by both supported rule segment representations.
type IsSegment interface {
	isSegment()
}

// SegmentKey is the shorthand form of a rule segment.
type SegmentKey string

func (SegmentKey) isSegment() {}

// Segments is the object form of a rule segment.
type Segments struct {
	Keys            []string `yaml:"keys"`
	SegmentOperator string   `yaml:"operator"`
}

func (Segments) isSegment() {}

// SegmentEmbed allows a rule's segment to be either a key or a group of keys.
type SegmentEmbed struct {
	IsSegment
}

// MarshalYAML preserves the representation held by SegmentEmbed.
func (s *SegmentEmbed) MarshalYAML() (interface{}, error) {
	if s == nil {
		return nil, fmt.Errorf("invalid segment: missing value")
	}

	switch segment := s.IsSegment.(type) {
	case SegmentKey:
		if segment == "" {
			return nil, fmt.Errorf("invalid segment: empty key")
		}
		return string(segment), nil
	case *SegmentKey:
		if segment == nil || *segment == "" {
			return nil, fmt.Errorf("invalid segment: empty key")
		}
		return string(*segment), nil
	case Segments:
		if len(segment.Keys) == 1 {
			segment.SegmentOperator = "OR_SEGMENT_OPERATOR"
		}
		if err := validateSegments(segment); err != nil {
			return nil, err
		}
		return segment, nil
	case *Segments:
		if segment == nil {
			return nil, fmt.Errorf("invalid segment: missing value")
		}
		value := *segment
		if len(value.Keys) == 1 {
			value.SegmentOperator = "OR_SEGMENT_OPERATOR"
		}
		if err := validateSegments(value); err != nil {
			return nil, err
		}
		return value, nil
	default:
		return nil, fmt.Errorf("invalid segment: unsupported value %T", s.IsSegment)
	}
}

// UnmarshalYAML accepts a key or an object with keys and an operator.
func (s *SegmentEmbed) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var raw interface{}
	if err := unmarshal(&raw); err != nil {
		return err
	}

	switch value := raw.(type) {
	case string:
		if value == "" {
			return fmt.Errorf("invalid segment: empty key")
		}
		s.IsSegment = SegmentKey(value)
		return nil
	case map[interface{}]interface{}:
		fields := make(map[string]interface{}, len(value))
		for key, field := range value {
			name, ok := key.(string)
			if !ok {
				return fmt.Errorf("invalid segment: unsupported field %v", key)
			}
			fields[name] = field
		}
		return s.unmarshalSegmentMap(fields)
	case map[string]interface{}:
		return s.unmarshalSegmentMap(value)
	default:
		return fmt.Errorf("invalid segment: expected a key or keys and operator, got %T", raw)
	}
}

func (s *SegmentEmbed) unmarshalSegmentMap(fields map[string]interface{}) error {
	var segment Segments
	var hasKeys, hasOperator bool
	var operatorValue interface{}
	for key, field := range fields {
		switch key {
		case "keys":
			hasKeys = true
			keys, ok := field.([]interface{})
			if !ok {
				return fmt.Errorf("invalid segment: keys must be a list of strings")
			}
			for _, key := range keys {
				name, ok := key.(string)
				if !ok || name == "" {
					return fmt.Errorf("invalid segment: keys must be nonempty strings")
				}
				segment.Keys = append(segment.Keys, name)
			}
		case "operator":
			hasOperator = true
			operatorValue = field
		default:
			return fmt.Errorf("invalid segment: unsupported field %v", key)
		}
	}
	if !hasKeys || len(segment.Keys) == 0 {
		return fmt.Errorf("invalid segment: keys must be a nonempty list")
	}
	if !hasOperator {
		return fmt.Errorf("invalid segment: missing operator")
	}
	if len(segment.Keys) == 1 {
		s.IsSegment = SegmentKey(segment.Keys[0])
		return nil
	}
	operator, ok := operatorValue.(string)
	if !ok {
		return fmt.Errorf("invalid segment: operator must be a string")
	}
	segment.SegmentOperator = operator
	if err := validateSegments(segment); err != nil {
		return err
	}
	s.IsSegment = segment
	return nil
}

func validateSegments(segment Segments) error {
	if len(segment.Keys) == 0 {
		return fmt.Errorf("invalid segment: keys must be a nonempty list")
	}
	for _, key := range segment.Keys {
		if key == "" {
			return fmt.Errorf("invalid segment: keys must be nonempty strings")
		}
	}
	if segment.SegmentOperator != "AND_SEGMENT_OPERATOR" && segment.SegmentOperator != "OR_SEGMENT_OPERATOR" {
		return fmt.Errorf("invalid segment: unsupported operator %q", segment.SegmentOperator)
	}
	return nil
}

type Distribution struct {
	VariantKey string  `yaml:"variant,omitempty"`
	Rollout    float32 `yaml:"rollout,omitempty"`
}

type Rollout struct {
	Description string         `yaml:"description,omitempty"`
	Segment     *SegmentRule   `yaml:"segment,omitempty"`
	Threshold   *ThresholdRule `yaml:"threshold,omitempty"`
}

type SegmentRule struct {
	Key      string   `yaml:"key,omitempty"`
	Keys     []string `yaml:"keys,omitempty"`
	Operator string   `yaml:"operator,omitempty"`
	Value    bool     `yaml:"value,omitempty"`
}

type ThresholdRule struct {
	Percentage float32 `yaml:"percentage,omitempty"`
	Value      bool    `yaml:"value,omitempty"`
}

type Segment struct {
	Key         string        `yaml:"key,omitempty"`
	Name        string        `yaml:"name,omitempty"`
	Description string        `yaml:"description,omitempty"`
	Constraints []*Constraint `yaml:"constraints,omitempty"`
	MatchType   string        `yaml:"match_type,omitempty"`
}

type Constraint struct {
	Type        string `yaml:"type,omitempty"`
	Property    string `yaml:"property,omitempty"`
	Operator    string `yaml:"operator,omitempty"`
	Value       string `yaml:"value,omitempty"`
	Description string `yaml:"description,omitempty"`
}

package ext

import (
	"testing"

	"github.com/stretchr/testify/require"
	"gopkg.in/yaml.v2"
	yamlv3 "gopkg.in/yaml.v3"
)

func TestRuleSegmentUnmarshalYAML(t *testing.T) {
	tests := []struct {
		name    string
		input   string
		segment IsSegment
		wantErr bool
	}{
		{name: "string", input: "segment: foo\n", segment: SegmentKey("foo")},
		{name: "object", input: "segment:\n  keys: [foo, bar]\n  operator: AND_SEGMENT_OPERATOR\n", segment: Segments{Keys: []string{"foo", "bar"}, SegmentOperator: "AND_SEGMENT_OPERATOR"}},
		{name: "single key object uses shorthand", input: "segment:\n  keys: [foo]\n  operator: AND_SEGMENT_OPERATOR\n", segment: SegmentKey("foo")},
		{name: "single key ignores operator", input: "segment:\n  keys: [foo]\n  operator: invalid\n", segment: SegmentKey("foo")},
		{name: "single key without operator", input: "segment:\n  keys: [foo]\n", wantErr: true},
		{name: "empty string", input: "segment: ''\n", wantErr: true},
		{name: "number", input: "segment: 42\n", wantErr: true},
		{name: "list", input: "segment: [foo]\n", wantErr: true},
		{name: "empty object", input: "segment: {}\n", wantErr: true},
		{name: "empty keys", input: "segment:\n  keys: []\n  operator: AND_SEGMENT_OPERATOR\n", wantErr: true},
		{name: "missing operator", input: "segment:\n  keys: [foo, bar]\n", wantErr: true},
		{name: "invalid operator", input: "segment:\n  keys: [foo, bar]\n  operator: invalid\n", wantErr: true},
		{name: "invalid key", input: "segment:\n  keys: [foo, 42]\n  operator: AND_SEGMENT_OPERATOR\n", wantErr: true},
		{name: "unknown field", input: "segment:\n  keys: [foo, bar]\n  operator: AND_SEGMENT_OPERATOR\n  extra: true\n", wantErr: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var rule Rule
			err := yaml.Unmarshal([]byte(tt.input), &rule)
			if tt.wantErr {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			require.NotNil(t, rule.Segment)
			require.Equal(t, tt.segment, rule.Segment.IsSegment)
		})
	}
}

func TestRuleSegmentUnmarshalYAMLv3(t *testing.T) {
	var rule Rule
	err := yamlv3.Unmarshal([]byte("segment:\n  keys: [foo, bar]\n  operator: AND_SEGMENT_OPERATOR\n"), &rule)
	require.NoError(t, err)
	require.Equal(t, Segments{Keys: []string{"foo", "bar"}, SegmentOperator: "AND_SEGMENT_OPERATOR"}, rule.Segment.IsSegment)
}

func TestRuleSegmentMarshalYAML(t *testing.T) {
	tests := []struct {
		name    string
		segment IsSegment
		want    string
		wantErr bool
	}{
		{name: "string", segment: SegmentKey("foo"), want: "segment: foo\n"},
		{name: "object", segment: Segments{Keys: []string{"foo", "bar"}, SegmentOperator: "AND_SEGMENT_OPERATOR"}, want: "segment:\n  keys:\n  - foo\n  - bar\n  operator: AND_SEGMENT_OPERATOR\n"},
		{name: "single key fallback", segment: Segments{Keys: []string{"foo"}, SegmentOperator: "AND_SEGMENT_OPERATOR"}, want: "segment:\n  keys:\n  - foo\n  operator: OR_SEGMENT_OPERATOR\n"},
		{name: "empty", wantErr: true},
		{name: "invalid operator", segment: Segments{Keys: []string{"foo", "bar"}, SegmentOperator: "invalid"}, wantErr: true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			out, err := yaml.Marshal(&Rule{Segment: &SegmentEmbed{IsSegment: tt.segment}})
			if tt.wantErr {
				require.Error(t, err)
				return
			}
			require.NoError(t, err)
			require.Equal(t, tt.want, string(out))
		})
	}
}

